<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
use Illuminate\Support\Facades\DB;
$l=DB::table('lessons')->first();$id=$l->id;
$segments=DB::selectOne("SELECT count(*)::int AS frames,coalesce(sum(sample_count),0)::bigint AS samples,count(DISTINCT epoch)::int AS epochs,count(*) FILTER(WHERE model_delivery='sent')::int AS model_sent FROM audio_segments WHERE lesson_id=?",[$id]);
$chunks=DB::table('audio_chunks')->where('lesson_id',$id)->selectRaw('storage_state,count(*)::int AS count')->groupBy('storage_state')->pluck('count','storage_state')->all();
$latency=DB::selectOne("SELECT min(extract(epoch FROM updated_at-created_at)*1000) AS min_ms,max(extract(epoch FROM updated_at-created_at)*1000) AS max_ms,percentile_cont(.95) WITHIN GROUP(ORDER BY extract(epoch FROM updated_at-created_at)*1000) AS p95_ms FROM audio_chunks WHERE lesson_id=? AND storage_state='uploaded'",[$id]);
$r=['at_ms'=>(int)round(microtime(true)*1000),'lesson'=>['status'=>$l->status,'media_samples'=>(int)$l->media_samples,'archive_status'=>$l->archive_status,'recorder_epoch'=>$l->recorder_epoch],'segments'=>$segments,'chunks'=>$chunks,'chunk_backup_delay_mock_ms'=>$latency,'queued_jobs'=>DB::table('jobs')->count(),'failed_jobs'=>DB::table('failed_jobs')->count(),'events'=>DB::table('lesson_events')->count(),'model_sessions'=>DB::table('model_sessions')->count(),'db_bytes'=>(int)DB::selectOne('SELECT pg_database_size(current_database()) AS bytes')->bytes,'disk_free_bytes'=>disk_free_space(storage_path())];
if(in_array('--final',$argv,true)){$r['timeline']=DB::selectOne('SELECT count(*) FILTER(WHERE start_sample<>previous_end)::int AS gaps,coalesce(max(start_sample+sample_count),0)::bigint AS end_sample FROM (SELECT start_sample,sample_count,lag(start_sample+sample_count,1,0::bigint) OVER(ORDER BY start_sample,id) AS previous_end FROM audio_segments WHERE lesson_id=?) t',[$id]);$r['completed_units']=DB::table('subtitle_units')->where('lesson_id',$id)->where('status','completed')->count();$r['archive']=DB::table('recordings')->where('lesson_id',$id)->select('bytes','sha256','duration_samples','status')->first();$bytes=0;$files=0;foreach(new RecursiveIteratorIterator(new RecursiveDirectoryIterator(storage_path(),FilesystemIterator::SKIP_DOTS))as$f)if($f->isFile()){$bytes+=$f->getSize();$files++;}$r['storage_bytes']=$bytes;$r['storage_files']=$files;}
if(in_array('--final',$argv,true)&&is_file(storage_path('../mock-metrics.ndjson'))){$previous=null;$first=null;$last=null;$maxGap=0;$gaps=[];$count=0;foreach(file(storage_path('../mock-metrics.ndjson'),FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES)as$line){$event=json_decode($line,true,16,JSON_THROW_ON_ERROR);if(($event['type']??'')!=='audio')continue;$at=(int)$event['at_ms'];$first??=$at;$last=$at;$count++;if($previous!==null){$gap=max(0,$at-$previous);$maxGap=max($maxGap,$gap);$gaps[]=$gap;}$previous=$at;}sort($gaps);$r['mock_receive_cadence']=['frames'=>$count,'first_to_last_wall_seconds'=>$first===null?0:($last-$first)/1000,'interval_p95_ms'=>$gaps?($gaps[(int)floor((count($gaps)-1)*.95)]):null,'interval_p99_ms'=>$gaps?($gaps[(int)floor((count($gaps)-1)*.99)]):null,'interval_max_ms'=>$maxGap,'intervals_above_500ms'=>count(array_filter($gaps,fn($gap)=>$gap>500))];}
echo json_encode($r,JSON_THROW_ON_ERROR).PHP_EOL;
